const ANIMATION_TOKEN_LOADING = new InjectionToken("ANIMATION_TOKEN_LOADING");

class LoadingService {
    loadingState = new BehaviorSubject(new Map());
    setLoading(loadingItem) {
        const currentLoading = this.loadingState.getValue();
        currentLoading.set(loadingItem.id, loadingItem);
        this.loadingState.next(new Map(currentLoading));
    }
    getLoading() {
        return this.loadingState.asObservable();
    }
    isAppLoading() {
        return this.loadingState.pipe(map((loadingItems) => {
            return Array.from(loadingItems.values()).some((item) => item.isLoading && !item?.metadata?.['ignoreGlobalLoading']);
        }));
    }
    getRequestLoading(reqId) {
        return this.loadingState.pipe(map(loadingItems => loadingItems.get(reqId)));
    }
    static ɵfac = i0.ɵɵngDeclareFactory({ minVersion: "12.0.0", version: "21.2.5", ngImport: i0, type: LoadingService, deps: [], target: i0.ɵɵFactoryTarget.Injectable });
    static ɵprov = i0.ɵɵngDeclareInjectable({ minVersion: "12.0.0", version: "21.2.5", ngImport: i0, type: LoadingService, providedIn: 'root' });
}
